class Player:
    def __init__(self, name, goals):
        self.name = name
        self._goals = 0
        self.goals = goals

    @property
    def goals(self):
        return self._goals

    @goals.setter
    def goals(self, value):
        try:
            val = int(value)
            if val < 0:
                self._goals = 0
            else:
                self._goals = val
        except (ValueError, TypeError):
            self._goals = 0

def main():
    import sys
    data = sys.stdin.read().strip().splitlines()
    i = 0
    results = []
    while i < len(data):
        line = data[i].strip()
        if ',' in line:
            parts = line.split(',')
            name = parts[0].strip()
            goals_val = parts[1].strip()
        else:
            name = line
            i += 1
            if i >= len(data):
                break
            goals_val = data[i].strip()

        player = Player(name, goals_val)
        results.append(player.name)
        results.append(player.goals)
        i += 1

    for r in results:
        print(r)

if __name__ == "__main__":
    main()
